return $input.all().map(item => {
  const r = item.json;

  let intro;

  switch (r.type) {
    case 'RAPPEL_J7':
      intro = 'Votre rendez-vous consulaire est prévu dans 7 jours.';
      break;

    case 'RAPPEL_J1':
      intro = 'Votre rendez-vous consulaire est prévu demain.';
      break;

    case 'RAPPEL_H2':
      intro = 'Votre rendez-vous consulaire est prévu dans environ 2 heures.';
      break;

    default:
      intro = 'Nous vous rappelons votre prochain rendez-vous consulaire.';
  }

  const date = new Date(r.debut);

  const dateFormatee = new Intl.DateTimeFormat('fr-FR', {
    timeZone: 'Europe/Paris',
    dateStyle: 'full'
  }).format(date);

  const heureFormatee = new Intl.DateTimeFormat('fr-FR', {
    timeZone: 'Europe/Paris',
    hour: '2-digit',
    minute: '2-digit'
  }).format(date);

  return {
    json: {
      ...r,

      email_subject: `Rappel rendez-vous ${r.service_nom} - ${r.reference}`,

      email_text: `Bonjour ${r.prenom || ''} ${r.nom || ''},

${intro}

Référence : ${r.reference}
Service : ${r.service_nom}
Lieu : ${r.site_nom}
Date : ${dateFormatee}
Heure : ${heureFormatee}

Merci de vous présenter à l'heure prévue avec les documents nécessaires à votre démarche.

En cas d'empêchement, utilisez votre espace de gestion pour annuler ou replanifier votre rendez-vous.

Cordialement,

Service consulaire`
    }
  };
});
